  AwakerStory_11342_Content = {
    Text = "Uyandırıcı'nın dosya yöneticisi, dosyasını birkaç kez öğrenci yönetimine aktardı, ancak o her seferinde dosyayı geri gönderip bir belge yığınının altına gömdü.\n\"Burada kalsın. Eninde sonunda teslim edilmesi gerekecek.\"\nSes tonu her zamanki gibi sakin, ama bakışları öngörülemez biçimde titreşiyor.\n\nBu sakinliğin altında ne devasa duygular yatıyor?"
  },
  AwakerStory_11342_Title = {
    Text = "Temel Bilgiler"
