  },
  AwakerStory_11347_Content = {
    Text = "\"Felaket Olayı Kayıtları III\"e göre Muhafız, bu Gümüş Çekirdek parçasını Londinium Yetimhanesi’nden geri getirmiştir. Gümüş Çekirdek’e, yamalarla kaplı küçücük bir oyuncak ayı eşlik ediyordu.\nBu Gümüş yaklaşık 2,1 gram ağırlığındadır, ince ve pürüzsüzdür, bir gözyaşını andırır. Gümüşle doğrudan temas edenler, Gümüş’e dokundukları pozu koruyarak Durgunluk Hâli’ne girer ve ancak bir başkası tarafından Uyandırıldıklarında normale dönerler. Kazara teması önlemek için Araştırmacı Bebek, bu Gümüş’ü kapalı bir cam küreye yerleştirmiş ve oyuncak ayının gözlerini değiştirmiştir.\n“Her gün ağlıyormuş gibi görünüyor.”"
  },
  AwakerStory_11347_Title = {Text = "Hikâye: I"},
